def comp8(cells):
    S=set(cells); seen=set(); comps=[]
    for c in sorted(S):
        if c in seen: continue
        q=deque([c]); seen.add(c); comp=[]
        while q:
            x,y=q.popleft(); comp.append((x,y))
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    if (dx,dy)==(0,0): continue
                    n=(x+dx,y+dy)
                    if n in S and n not in seen: seen.add(n); q.append(n)
        comps.append(comp)
    return comps
