from collections import deque as dq
def bfs_from(starts, mask):
    dist={s:0 for s in starts}
    q=dq(starts)
    while q:
        x,y=q.popleft()
        for dx in (-1,0,1):
            for dy in (-1,0,1):
                if dx==0 and dy==0: continue
                n=(x+dx,y+dy)
                if 0<=n[0]<mask.shape[0] and 0<=n[1]<mask.shape[1] and mask[n]==0 and n not in dist:
                    dist[n]=dist[(x,y)]+1; q.append(n)
    return dist
