def occ_fuzzy(Ig, shape, K):
    Hh,Ww=Ig.shape
    h=max(x for x,y in shape)+1; w=max(y for x,y in shape)+1
    covered=set(); locs=[]
    for i in range(Hh-h+1):
        for j in range(Ww-w+1):
            cells={(i+dx,j+dy) for dx,dy in shape}
            if sum(Ig[i+dx,j+dy]==0 for dx,dy in shape)>=K:
                locs.append((i,j))
                covered|={c for c in cells if Ig[c]==0}
    return locs,covered
