def covcounts(Ig, shape, ors):
    Hh,Ww=Ig.shape
    cnt=Counter()
    for sh in ors:
        h=max(x for x,y in sh)+1; w=max(y for x,y in sh)+1
        for i in range(Hh-h+1):
            for j in range(Ww-w+1):
                if all(Ig[i+dx,j+dy]==0 for dx,dy in sh):
                    for dx,dy in sh: cnt[(i+dx,j+dy)]+=1
    return cnt
